  return (
    <StudentFeedbackContext.Provider
      value={{
        feedback,
        addFeedbackQuestion,
        handleFeedbackChange,
        handleSubmit
      }}
    >
      {children}
    </StudentFeedbackContext.Provider>
  );
};

export { StudentFeedbackContext, StudentFeedbackProvider };
