  <meta charset="UTF-8">
  <title>Pendulum Applet</title>
  <style>
    /* Styles for the applet */
    #pendulum {
      border: 1px solid black;
      width: 200px;
      height: 200px;
      margin: 20px auto;
    }
    #angleInput {
      width: 50px;
    }
  </style>
</head>
<body>
  <h1>Pendulum Applet</h1>
  <div id="pendulum">
    <!-- Pendulum canvas element -->
    <canvas id="canvas" width="200" height="200"></canvas>
  </div>
  <input id="angleInput" type="number" value="30"> degrees<br>
  <button id="releaseButton">Release Pendulum</button>
  <script>
    // Get the canvas element
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');

    // Set the initial angle
    let initialAngle = 30;

    // Set the initial velocity
    let velocity = 0;

    // Set the gravitational constant
    const g = 9.81;

    // Set the length of the pendulum
    const pendulumLength = canvas.height / 2;

    // Set the pendulum's angular velocity
    let angularVelocity = 0;

    // Set the pendulum's angular acceleration
    let angularAcceleration = 0;

    // Function to update the pendulum's position
    function updatePendulum() {
      // Calculate the pendulum's angular position
      let angle = initialAngle + velocity / pendulumLength;

      // Calculate the pendulum's angular velocity
      angularVelocity = angularAcceleration;
      angularAcceleration = -g / pendulumLength * Math.sin(angle);

      // Update the velocity
      velocity += angularVelocity;

      // Clear the canvas
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Draw the pendulum
      ctx.beginPath();
      ctx.strokeStyle = 'black';
      ctx.lineWidth = 2;
      ctx.moveTo(canvas.width / 2, canvas.height);
      ctx.lineTo(canvas.width / 2 + pendulumLength * Math.sin(angle), canvas.height - pendulumLength * Math.cos(angle));
      ctx.stroke();

      // Update the requestAnimationFrame
      requestAnimationFrame(updatePendulum);
    }

    // Function to handle the release button click
    document.getElementById('releaseButton').addEventListener('click', () => {
      // Stop the animation if it's already running
      if (requestAnimationFrame.id) {
        cancelAnimationFrame(requestAnimationFrame.id);
      }

      // Start the animation
      requestAnimationFrame(updatePendulum);
    });

    // Update the pendulum's position on the initial setup
    updatePendulum();
  </script>
</body>
</html>
```

